      if (pr.state === 'closed') return tag({ tone: 'danger', children: t('pr.closed') })
      if (pr.draft === true) return tag({ tone: 'warning', children: t('pr.draft') })
      if (pr.state === 'open') return tag({ tone: 'success', children: t('pr.open') })
